<script setup lang="ts">import { computed } from 'vue';const props=withDefaults(defineProps<{value:number;max:number;tone?:'brand'|'success'|'warn'|'danger';label?:string;unit?:string;size?:number}>(),{tone:'brand',label:'',unit:'',size:112});const percent=computed(()=>props.max>0?Math.max(0,Math.min(100,props.value/props.max*100)):0)</script>
<template><div class="ring-progress" :class="`tone-${tone}`" :style="{width:`${size}px`,height:`${size}px`}" role="progressbar" :aria-valuenow="value" :aria-valuemax="max"><svg viewBox="0 0 42 42" aria-hidden="true"><circle class="ring-track" cx="21" cy="21" r="17"/><circle class="ring-value" cx="21" cy="21" r="17" pathLength="100" :stroke-dasharray="`${percent} ${100-percent}`"/></svg><div><strong>{{Math.round(value)}}</strong><small>{{unit}}</small><span>{{label}}</span></div></div></template>
